// ProjectOS dashboard - server-side auth gate (single owner).
// Dashboard HTML is EMBEDDED (base64) in this function - NO static file is deployed to leak.
// Public URL, but dashboard/data served ONLY after login. Built-in crypto only. Secrets from Vercel env.
const crypto = require('crypto');

const COOKIE = 'pos_sess';
const MAX_AGE = 60 * 60 * 8; // 8h
const DASH_B64 = "";

function secret() { return process.env.SESSION_SECRET || ''; }
function configured() { return !!(process.env.SESSION_SECRET && process.env.DASH_PASSWORD_HASH); }
function sign(p) { return crypto.createHmac('sha256', secret()).update(p).digest('hex'); }
function makeToken() { const e = String(Math.floor(Date.now()/1000)+MAX_AGE); return e+'.'+sign(e); }
function verifyToken(t) {
  if (!t || !secret()) return false;
  const i = t.lastIndexOf('.'); if (i < 0) return false;
  const p = t.slice(0,i), s = t.slice(i+1), g = sign(p);
  if (s.length !== g.length) return false;
  if (!crypto.timingSafeEqual(Buffer.from(s), Buffer.from(g))) return false;
  const e = parseInt(p,10); return !!e && e >= Math.floor(Date.now()/1000);
}
function parseCookies(req) {
  const o = {}; (req.headers.cookie || '').split(';').forEach(function(p){ const i=p.indexOf('='); if(i>-1)o[p.slice(0,i).trim()]=p.slice(i+1).trim(); }); return o;
}
function sha256(s){ return crypto.createHash('sha256').update(s).digest('hex'); }
function safeEq(a,b){ const x=Buffer.from(String(a)),y=Buffer.from(String(b)); if(x.length!==y.length)return false; return crypto.timingSafeEqual(x,y); }
function readBody(req){ return new Promise(function(r){ let d=''; req.on('data',function(c){ d+=c; if(d.length>1e6) req.destroy(); }); req.on('end',function(){ r(d); }); }); }

let DASH = null;
function dashboard(){ if (DASH === null) DASH = Buffer.from(DASH_B64,'base64').toString('utf8'); return DASH; }

function loginPage(err, notCfg) {
  const msg = notCfg
    ? '<p class="warn">Login not configured. Set SESSION_SECRET, DASH_PASSWORD_HASH (+ optional DASH_USER) in Vercel env, then redeploy.</p>'
    : (err ? '<p class="err">Incorrect username or password.</p>' : '');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">' +
    '<title>ProjectOS - Sign in</title><style>' +
    ':root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;' +
    'background:#0b0e14;font:15px/1.5 ui-sans-serif,system-ui,Segoe UI,Roboto,sans-serif;color:#e6e9ef}' +
    '.card{width:min(92vw,360px);background:#121722;border:1px solid #232b3a;border-radius:14px;padding:28px 26px;box-shadow:0 12px 40px rgba(0,0,0,.5)}' +
    'h1{margin:0 0 4px;font-size:18px}.sub{margin:0 0 18px;color:#8b93a7;font-size:12.5px}' +
    'label{display:block;font-size:12px;color:#9aa3b7;margin:12px 0 5px}' +
    'input{width:100%;padding:10px 12px;background:#0b0e14;border:1px solid #2a3346;border-radius:9px;color:#e6e9ef;font-size:14px}' +
    'input:focus{outline:none;border-color:#3b82f6}button{margin-top:18px;width:100%;padding:11px;border:0;border-radius:9px;cursor:pointer;background:#3b82f6;color:#fff;font-size:14px;font-weight:600}' +
    'button:hover{background:#2f6fd6}.err{color:#f87171;font-size:12.5px;margin:12px 0 0}.warn{color:#fbbf24;font-size:12px;margin:12px 0 0}.foot{margin-top:16px;color:#5b6472;font-size:11px;text-align:center}' +
    '</style></head><body><form class="card" method="POST" action="/?action=login">' +
    '<h1>ProjectOS</h1><p class="sub">Owner cockpit - sign in to continue</p>' +
    '<label for="u">Username</label><input id="u" name="username" autocomplete="username" autofocus>' +
    '<label for="p">Password</label><input id="p" name="password" type="password" autocomplete="current-password">' +
    '<button type="submit">Sign in</button>' + msg +
    '<div class="foot">Private. Evidence-only. No approval/deploy/DB/send/payment authority.</div>' +
    '</form></body></html>';
}

module.exports = async function (req, res) {
  let action=''; try { action = new URL(req.url,'http://x').searchParams.get('action') || ''; } catch(e){}
  const authed = verifyToken(parseCookies(req)[COOKIE]);
  const H = function(){ res.setHeader('Content-Type','text/html; charset=utf-8'); res.setHeader('Cache-Control','no-store'); res.setHeader('X-Content-Type-Options','nosniff'); res.setHeader('X-Frame-Options','DENY'); res.setHeader('Referrer-Policy','no-referrer'); };

  if (action === 'logout') { res.setHeader('Set-Cookie', COOKIE+'=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0'); res.statusCode=302; res.setHeader('Location','/'); res.end(); return; }

  if (req.method === 'POST' && action === 'login') {
    if (!configured()) { res.statusCode=503; H(); res.end(loginPage(false,true)); return; }
    const body = await readBody(req); const p = new URLSearchParams(body);
    const okUser = !process.env.DASH_USER || safeEq(p.get('username')||'', process.env.DASH_USER);
    const okPass = safeEq(sha256(p.get('password')||''), process.env.DASH_PASSWORD_HASH || 'x');
    if (okUser && okPass) { res.setHeader('Set-Cookie', COOKIE+'='+makeToken()+'; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age='+MAX_AGE); res.statusCode=302; res.setHeader('Location','/'); res.end(); return; }
    res.statusCode=401; H(); res.end(loginPage(true,false)); return;
  }

  if (!authed) { res.statusCode=200; H(); res.end(loginPage(false, !configured())); return; }
  res.statusCode=200; H(); res.end(dashboard());
};